"""ExceptionTriageAgent — generated by G2C (e2a_inherited); hooks implemented by hand.

PROPOSES one resolution for a reconciliation exception. It never executes: the
service re-validates every proposal with deterministic rules and executes it
only through conditional writes (E2A: probabilistic intelligence proposes,
deterministic controls authorize, execute and confirm).
"""
import json
import logging

from e2a_base import BaseAgent

from ..models.records import Proposal
from ..services.llm import AGENT_MARKER

ALLOWED = ("MATCH", "MATCH_WITH_WRITE_OFF", "REFUND_DUPLICATE", "REQUEST_REMITTANCE")
SAFE_DEFAULT = Proposal(action="REQUEST_REMITTANCE", rationale="fallback: ask the payer for remittance advice")


class ExceptionTriageAgent(BaseAgent):
    """Inherits the public entry point and every NFR from BaseAgent.
    Input validation is a _validate_exception_triage_agent validator on the
    BaseValidationService subclass; the model is reached only through
    config['llm_service']."""
    agent_name = 'ExceptionTriageAgent'

    def _build_messages(self, state, config=None, **kwargs) -> list:
        line = state['line']
        lines = [f"Exception: {state['kind']}", f"Detail: {state['detail']}",
                 f"Line amount: {line['amount']}", f"Line currency: {line['currency']}",
                 f"Counterparty: {line['counterparty_account']}", "Candidates:"]
        lines += [f"- candidate {c['settlement_id']} amount {c['amount']}" for c in state['candidates']]
        return [{'role': 'system', 'content': f'You are the {AGENT_MARKER}. Propose exactly one action as JSON '
                                              f'{{"action", "settlement_ids", "rationale"}}; action is one of {", ".join(ALLOWED)}.'},
                {'role': 'user', 'content': '\n'.join(lines)}]

    def _apply_policy(self, state, config=None, **kwargs) -> None:
        approved = (config or {}).get('approved_agents')            # kept from the G2C skeleton
        if approved is not None and self.agent_name not in approved:
            raise PermissionError(f'{self.agent_name} is not an approved agent')
        if not state.get('tenant_id'):
            raise PermissionError('a tenant is required')
        if state.get('kind') not in ('UNMATCHED', 'AMBIGUOUS', 'DUPLICATE'):
            raise ValueError(f"unknown exception kind {state.get('kind')}")

    def _evaluate_output(self, response, state, config=None, **kwargs) -> float:
        """Structured-output check: valid JSON, an allowed action, only known candidates."""
        text = (response or {}).get('text', '') if isinstance(response, dict) else str(response or '')
        try:
            proposal = Proposal.model_validate(json.loads(text))
        except (ValueError, TypeError):
            return 0.0
        known = {c['settlement_id'] for c in state['candidates']}
        if not set(proposal.settlement_ids) <= known:
            return 0.0
        state['proposal'] = proposal
        return 1.0

    def _fallback(self, state, config=None, **kwargs):
        state['proposal'] = SAFE_DEFAULT
        return {'text': SAFE_DEFAULT.model_dump_json(), 'degraded': True}

    def _handle_error(self, error, state, config=None, **kwargs):
        logging.error(f'[{self.agent_name}] {error}')
        state.setdefault('errors', []).append(str(error))
        state['proposal'] = SAFE_DEFAULT
        return state
